import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
terms=['("macula densa"[Title/Abstract]) AND (oxidative OR redox OR ROS) AND "tubuloglomerular feedback"','("macula densa"[Title/Abstract]) AND "angiotensin II" AND "tubuloglomerular feedback"','"tubuloglomerular feedback" AND oxidative stress AND hypertension']
for term in terms:
 r=requests.get(u,params={'db':'pubmed','term':term,'retmax':15,'retmode':'json'},timeout=20)
 ids=r.json()['esearchresult']['idlist']
 print('\nQUERY',term,'\nPMIDS',ids)
 if ids:
  f=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i, f[i].get('title',''), f[i].get('pubdate',''))
